  before_data String?

  /// Serialized JSON snapshot of the entity state after the change.
  ///
  /// Null for delete and access events, where no resulting state exists;
  /// combined with beforeData it forms the before/after diff demanded by the
  /// audit specification.
  after_data String?

  /// Timestamp when the event was recorded.
  ///
  /// Doubles as the occurrence moment because rows are immutable once written;
  /// updatedAt and deletedAt are intentionally absent from this append-only
  /// trail.
  created_at DateTime @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  organization broker_desk_organizations @relation(fields: [broker_desk_organization_id], references: [id], onDelete: Cascade)

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  adminAttribution    broker_desk_audit_log_of_admins?
  producerAttribution broker_desk_audit_log_of_producers?
  ofCsr               broker_desk_audit_log_of_csrs?

  //----
  // INDEXES
  //----
  @@index([actor_type])
  // spellchecker: ignore-next-line
  @@index([broker_desk_organization_id, created_at], map: "broker_desk_audit_logs_broker_desk_organization_id_cre_97700dfa")
  // spellchecker: ignore-next-line
